int get_bluetooth_sock_name(struct socket *sock, struct sockaddr *addr, int *addr_len, int peer)
{
    struct sockaddr_hci *hciaddr = (struct sockaddr_hci *)addr;
    struct hci_dev *hdev;

    if (!sock || !addr || !addr_len)
        return -EBADFD;

    hdev = hci_get_dev_by_sock(sock);
    if (!hdev)
        return -EBADFD;

    sock->sk->sk_lock.lock();
    hciaddr->hci_family = AF_BLUETOOTH;
    hciaddr->hci_dev = hdev->id;
    hciaddr->hci_channel = peer ? HCI_CHAN_REMOTE : HCI_CHAN_LOCAL;
    sock->sk->sk_lock.unlock();

    *addr_len = sizeof(struct sockaddr_hci);
    return 0;
}

int get_bt_sock_name(struct socket *sock, struct sockaddr *addr, int *addr_len, int peer)
{
    struct sockaddr_hci *hci_addr = (struct sockaddr_hci *)addr;
    struct bt_sock *bt_sk = bt_sk(sock->sk);

    if (!bt_sk->hdev) {
        return -EBADFD;
    }

    lock_sock(sock->sk);

    hci_addr->hci_family = AF_BLUETOOTH;
    hci_addr->hci_dev = bt_sk->hdev->id;
    hci_addr->hci_channel = bt_sk->channel;

    *addr_len = sizeof(*hci_addr);

    release_sock(sock->sk);

    return 0;
}

